    auto report=argc>1?std::filesystem::path(argv[1]):L"ui-gpu-results";std::filesystem::create_directories(report);
    if(!reshade::register_addon(GetModuleHandleW(nullptr),GetModuleHandleW(L"dxgi.dll")))throw std::runtime_error("ReShade addon registration failed");
